function enhanceWidgetLibrary(){var panel=all('.cc-studio-left .cc-studio-panel',root).find(function(p){return text(one('.cc-studio-panel-head strong',p))==='Add widgets';});if(!panel)return;var search=one('.cc-studio-search',panel);if(search&&!one('.cc-studio-ux-library-filters',panel)){var filters=document.createElement('div');filters.className='cc-studio-ux-library-filters';['All','Favorites','Recent','Recommended'].forEach(function(label){var button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.filter=label.toLowerCase();button.addEventListener('click',function(){storeWrite(FILTER_KEY,button.dataset.filter);applyWidgetFilter(panel,button.dataset.filter);});filters.appendChild(button);});search.parentNode.insertBefore(filters,search.nextSibling);}all('.cc-studio-widget-grid button',panel).forEach(function(tile){if(tile.dataset.uxEnhanced==='1')return;tile.dataset.uxEnhanced='1';var small=one('small',tile),type=small?text(small):'';tile.dataset.uxType=type;var star=document.createElement('span');star.className='cc-studio-ux-favorite-star dashicons dashicons-star-empty';star.setAttribute('role','button');star.setAttribute('tabindex','0');star.setAttribute('aria-label','Toggle favorite');star.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();toggleFavorite(type);schedule();});star.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();toggleFavorite(type);schedule();}});tile.appendChild(star);tile.addEventListener('click',function(){rememberRecent(type);});});applyWidgetFilter(panel,storeRead(FILTER_KEY,'all'));}
function favorites(){return arr(storeRead(FAVORITES_KEY,[]));}
function recents(){return arr(storeRead(RECENTS_KEY,[]));}
function toggleFavorite(type){var list=favorites(),i=list.indexOf(type);if(i>=0)list.splice(i,1);else list.unshift(type);storeWrite(FAVORITES_KEY,list.slice(0,40));}
