function applyWidgetFilter(panel,filter){filter=filter||'all';var fav=favorites(),recent=recents(),recommended=recommendedWidgetTypes();all('.cc-studio-ux-library-filters button',panel).forEach(function(b){b.classList.toggle('is-active',b.dataset.filter===filter);});all('.cc-studio-widget-grid button',panel).forEach(function(tile){var type=tile.dataset.uxType||'',show=filter==='all'||(filter==='favorites'&&fav.indexOf(type)>=0)||(filter==='recent'&&recent.indexOf(type)>=0)||(filter==='recommended'&&recommended.indexOf(type)>=0);tile.hidden=!show;var star=one('.cc-studio-ux-favorite-star',tile);if(star){var active=fav.indexOf(type)>=0;star.classList.toggle('dashicons-star-filled',active);star.classList.toggle('dashicons-star-empty',!active);star.classList.toggle('is-active',active);}});all('.cc-studio-widget-group',panel).forEach(function(group){group.hidden=!all('.cc-studio-widget-grid button:not([hidden])',group).length;});}

function enhanceStructure(){if(!latestSession)return;all('.cc-studio-tree-row[data-cresco-node-id]',root).forEach(function(row){var id=row.dataset.crescoNodeId,node=findNode(latestSession,id);if(!node)return;var badges=one('.cc-studio-ux-tree-badges',row);if(!badges){badges=document.createElement('span');badges.className='cc-studio-ux-tree-badges';var actions=one('.cc-studio-tree-actions',row);row.insertBefore(badges,actions||null);}badges.innerHTML='';var items=[];if(Object.keys(obj(node.responsive)).length)items.push(['R','Responsive overrides']);if(Object.keys(obj(node.customCSS)).length)items.push(['CSS','Custom CSS']);if(obj(node.meta).componentId)items.push(['C','Component instance']);if(/^dynamic-|loop-|woo-/.test(String(node.type)))items.push(['D','Dynamic data']);items.forEach(function(item){var badge=document.createElement('span');badge.textContent=item[0];badge.title=item[1];badges.appendChild(badge);});});enhanceStructureHeader();}
function enhanceStructureHeader(){var structure=one('.cc-studio-structure',root);if(!structure)return;var header=one(':scope > header',structure);if(header&&!one('.cc-studio-ux-structure-actions',header)){var actions=document.createElement('span');actions.className='cc-studio-ux-structure-actions';actions.innerHTML='<button type="button" title="Collapse Structure" aria-label="Collapse Structure"><span class="dashicons dashicons-arrow-right-alt2"></span></button>';one('button',actions).addEventListener('click',toggleRightPane);header.appendChild(actions);}}
function enhanceGlobalDesign(){var panel=all('.cc-studio-left .cc-studio-panel',root).find(function(p){return text(one('.cc-studio-panel-head strong',p))==='Global Design';});if(!panel||panel.dataset.uxEnhanced==='1')return;panel.dataset.uxEnhanced='1';panel.classList.add('cc-studio-ux-global');var head=one('.cc-studio-panel-head',panel),search=document.createElement('label');search.className='cc-studio-ux-token-search';search.innerHTML='<span class="dashicons dashicons-search" aria-hidden="true"></span><input type="search" placeholder="Search design tokens…" aria-label="Search design tokens">';head.parentNode.insertBefore(search,head.nextSibling);one('input',search).addEventListener('input',function(){var q=this.value.toLowerCase();all('.cc-studio-token-list button',panel).forEach(function(b){b.hidden=!!q&&text(b).toLowerCase().indexOf(q)<0;});});var sessionText=latestSession?JSON.stringify(latestSession):'';all('.cc-studio-token-list button',panel).forEach(function(button){var code=one('code',button),value=one('span',button);if(!code||!value)return;var path=text(code),raw=text(value);if(/^#(?:[0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(raw)&&!one('.cc-studio-ux-swatch',button)){var swatch=document.createElement('i');swatch.className='cc-studio-ux-swatch';swatch.style.background=raw;button.insertBefore(swatch,code);}var token='{'+path+'}',uses=sessionText?sessionText.split(token).length-1:0;if(uses&&!one('.cc-studio-ux-uses',button)){var count=document.createElement('b');count.className='cc-studio-ux-uses';count.textContent=uses+' use'+(uses===1?'':'s');button.appendChild(count);}});}

function enhanceCanvas(){var selected=one('.cc-studio-canvas-node.is-selected[data-cresco-id]',root),badge=one('.cc-studio-ux-measure',root);if(!selected){if(badge)badge.remove();return;}var rect=selected.getBoundingClientRect(),cs=window.getComputedStyle(selected);if(!badge){badge=document.createElement('div');badge.className='cc-studio-ux-measure';selected.appendChild(badge);}else if(badge.parentNode!==selected)selected.appendChild(badge);var pad=[cs.paddingTop,cs.paddingRight,cs.paddingBottom,cs.paddingLeft].join(' ');badge.textContent=Math.round(rect.width)+' × '+Math.round(rect.height)+' · P '+pad+(cs.gap&&cs.gap!=='normal'?' · G '+cs.gap:'');enhanceBreadcrumb();}
function enhanceBreadcrumb(){var toolbar=one('.cc-studio-viewport-toolbar',root);if(!toolbar)return;var crumb=one('.cc-studio-ux-breadcrumb',toolbar);if(!crumb){crumb=document.createElement('div');crumb.className='cc-studio-ux-breadcrumb';toolbar.appendChild(crumb);}var ids=selectedIdsFromDom();if(!ids.length){crumb.textContent='Page';return;}var id=ids[0],trail=[],info=nodeInfo(latestSession,id);while(info){trail.unshift(obj(info.node.meta).label||info.node.type);info=info.parentId?nodeInfo(latestSession,info.parentId):null;}crumb.textContent=trail.join('  ›  ');}
function enhanceEmptyState(){var empty=one('.cc-studio-canvas-empty',root);if(!empty||one('.cc-studio-ux-empty-actions',empty))return;var actions=document.createElement('div');actions.className='cc-studio-ux-empty-actions';actions.innerHTML='<button type="button" class="is-primary">Start with a pattern</button><button type="button">Design with AI</button>';var buttons=all('button',actions);buttons[0].addEventListener('click',function(e){e.stopPropagation();clickRail('Patterns');});buttons[1].addEventListener('click',function(e){e.stopPropagation();clickRail('Design Director');});empty.appendChild(actions);}

function enhanceTopbar(){var actions=one('.cc-studio-top-actions',root),app=one('.cc-studio-app',root);if(!actions||!app)return;if(!one('.cc-studio-ux-top-actions',actions)){var wrap=document.createElement('span');wrap.className='cc-studio-ux-top-actions';wrap.innerHTML='<button type="button" class="cc-studio-icon-btn" data-action="left" title="Toggle left panel" aria-label="Toggle left panel"><span class="dashicons dashicons-arrow-left-alt2"></span></button><button type="button" class="cc-studio-icon-btn" data-action="focus" title="Focus mode" aria-label="Focus mode"><span class="dashicons dashicons-editor-expand"></span></button><button type="button" class="cc-studio-icon-btn" data-action="theme" title="Studio appearance" aria-label="Studio appearance"><span class="dashicons dashicons-admin-appearance"></span></button><button type="button" class="cc-studio-icon-btn" data-action="right" title="Toggle Structure" aria-label="Toggle Structure"><span class="dashicons dashicons-arrow-right-alt2"></span></button>';one('[data-action="left"]',wrap).addEventListener('click',toggleLeftPane);one('[data-action="right"]',wrap).addEventListener('click',toggleRightPane);one('[data-action="focus"]',wrap).addEventListener('click',toggleFocusMode);one('[data-action="theme"]',wrap).addEventListener('click',cycleTheme);actions.insertBefore(wrap,actions.firstChild);}installResizers();}
function installResizers(){var workspace=one('.cc-studio-workspace',root),app=one('.cc-studio-app',root);if(!workspace||!app)return;['left','right'].forEach(function(side){var handle=one('.cc-studio-ux-resizer.is-'+side,workspace);if(handle)return;handle=document.createElement('div');handle.className='cc-studio-ux-resizer is-'+side;handle.setAttribute('role','separator');handle.setAttribute('aria-orientation','vertical');handle.setAttribute('tabindex','0');handle.title='Drag to resize panel';workspace.appendChild(handle);handle.addEventListener('pointerdown',function(e){if(app.classList.contains('is-ux-focus'))return;e.preventDefault();handle.setPointerCapture(e.pointerId);document.body.classList.add('cc-studio-ux-resizing');function move(ev){var rail=parseFloat(window.getComputedStyle(app).getPropertyValue('--cc-ux-rail-width'))||64;if(side==='left'){var value=clamp(ev.clientX-rail,240,520);app.style.setProperty('--cc-ux-left-width',value+'px');storeWrite(LEFT_WIDTH_KEY,value);}else{var value=clamp(window.innerWidth-ev.clientX,260,520);app.style.setProperty('--cc-ux-right-width',value+'px');storeWrite(RIGHT_WIDTH_KEY,value);}}function up(ev){document.body.classList.remove('cc-studio-ux-resizing');handle.releasePointerCapture(ev.pointerId);handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',up);}handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',up);});});}
function toggleLeftPane(){var app=one('.cc-studio-app',root);if(!app)return;app.classList.toggle('is-ux-left-collapsed');}
