function toggleFocusMode(){var app=one('.cc-studio-app',root);if(!app)return;var enabled=!app.classList.contains('is-ux-focus');app.classList.toggle('is-ux-focus',enabled);storeWrite(FOCUS_KEY,enabled);showToast(enabled?'Focus mode enabled. Press F to exit.':'Focus mode disabled.','info');}
function applyTheme(theme){theme=theme||'system';storeWrite(THEME_KEY,theme);var dark=theme==='dark'||(theme==='system'&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.setAttribute('data-cc-theme',dark?'dark':'light');var app=one('.cc-studio-app',root);if(app)app.dataset.uxTheme=theme;}
function cycleTheme(){var current=storeRead(THEME_KEY,'system'),next=current==='system'?'light':current==='light'?'dark':'system';applyTheme(next);showToast('Studio appearance: '+next+'.','info');}
