function enhanceNotices(){all('.cc-studio-notice.is-error',root).forEach(function(notice){if(notice.dataset.uxEnhanced==='1')return;notice.dataset.uxEnhanced='1';notice.classList.add('cc-studio-ux-diagnostic');var msg=text(notice).toLowerCase();var hint='Open Quality for more context.';if(msg.indexOf('unsupported structured style property')>=0)hint='A style was placed on a widget that does not support it. Move layout properties to a parent Container.';else if(msg.indexOf('target')>=0)hint='The result no longer matches the exported edit scope. Re-export the intended selection.';else if(msg.indexOf('invalid json')>=0)hint='Check the JSON envelope and declared schema.';var small=document.createElement('small');small.textContent=hint;notice.appendChild(small);var button=document.createElement('button');button.type='button';button.textContent='Open Quality';button.addEventListener('click',function(){clickRail('Quality');});notice.appendChild(button);});}

