function keyboard(e){var typing=e.target&&(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable);if(typing)return;if(e.key==='f'||e.key==='F'){e.preventDefault();toggleFocusMode();}else if(e.shiftKey&&(e.key==='D'||e.key==='d')){e.preventDefault();clickRail('Design Director');}else if(e.shiftKey&&(e.key==='Q'||e.key==='q')){e.preventDefault();clickRail('Quality');}}
